/**
 * FileItem Component - Displays a single file
 * 
 * Responsibilities:
 * - Show file name, size, type
 * - Handle file click (download)
 * - Show file icon based on type
 * 
 * Import rules:
 * - Can import: hooks (if needed)
 * - Can import: other components
 * - Should NOT import: services, pages
 */

import React, { useState, useEffect, useRef } from 'react';
import { getFileIcon, formatFileSize } from '../../utils/helpers';
import { filesService } from '../../services';
import ShareModal from '../ShareModal/ShareModal';

const FileItem = ({ 
  file, 
  onDownload, 
  onDelete, 
  onRename,
  onMove,
  onCopy,
  onShare,
  isSelected = false,
  onSelect,
  viewMode = 'list' 
}) => {
  const [isHovered, setIsHovered] = useState(false);
  const [showMenu, setShowMenu] = useState(false);
  const [imageUrl, setImageUrl] = useState(null);
  const [imageLoading, setImageLoading] = useState(false);
  const [imageError, setImageError] = useState(false);
  const [showShareModal, setShowShareModal] = useState(false);
  const menuRef = useRef(null);

  // Handle both size and size_bytes field names
  const fileSize = file.size || file.size_bytes || 0;
  const mimeType = file.mime_type || file.mimeType || '';
  const isImage = mimeType.startsWith('image/');

  // Fetch image preview URL for grid view
  useEffect(() => {
    if (viewMode === 'grid' && isImage && file.id) {
      setImageLoading(true);
      setImageError(false);

      filesService.getSignedUrl(file.id)
        .then((response) => {
          const signedUrl = response?.data?.url || response?.url;
          if (signedUrl) {
            setImageUrl(signedUrl);
          } else {
            setImageError(true);
          }
        })
        .catch((error) => {
          console.error('Failed to load image preview:', error);
          setImageError(true);
        })
        .finally(() => {
          setImageLoading(false);
        });
    }
  }, [viewMode, isImage, file.id]);

  // Close menu when clicking outside and adjust position
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (menuRef.current && !menuRef.current.contains(event.target)) {
        setShowMenu(false);
      }
    };

    const adjustMenuPosition = () => {
      if (menuRef.current && showMenu) {
        const menu = menuRef.current.querySelector('.file-menu-dropdown');
        const button = menuRef.current.querySelector('.file-menu-btn');
        if (menu && button) {
          // Get button position relative to viewport
          const buttonRect = button.getBoundingClientRect();
          const padding = 12;
          const windowWidth = window.innerWidth;
          const windowHeight = window.innerHeight;

          // Reset styles first
          menu.style.position = 'absolute';
          menu.style.left = '';
          menu.style.right = '0';
          menu.style.top = '100%';
          menu.style.bottom = '';
          menu.style.marginTop = '4px';
          menu.style.marginBottom = '';
          menu.style.transform = '';
          menu.style.maxHeight = '';
          menu.style.overflowY = '';

          // Wait for render, then check if adjustments needed
          setTimeout(() => {
            const menuRect = menu.getBoundingClientRect();
            const menuHeight = menuRect.height;

            // Check horizontal positioning
            if (menuRect.right > windowWidth - padding) {
              menu.style.right = '0';
              menu.style.left = 'auto';
            }

            if (menuRect.left < padding) {
              menu.style.left = '0';
              menu.style.right = 'auto';
            }

            // Check vertical positioning - flip above if needed
            const spaceBelow = windowHeight - buttonRect.bottom;
            const spaceAbove = buttonRect.top;

            if (spaceBelow < menuHeight + padding && spaceAbove > menuHeight + padding) {
              // Position above the button
              menu.style.top = 'auto';
              menu.style.bottom = '100%';
              menu.style.marginTop = '0';
              menu.style.marginBottom = '4px';
            } else if (spaceBelow < menuHeight + padding) {
              // Not enough space below - try to fit it
              if (spaceAbove > spaceBelow) {
                // More space above, position above
                menu.style.top = 'auto';
                menu.style.bottom = '100%';
                menu.style.marginTop = '0';
                menu.style.marginBottom = '4px';
              } else {
                // Constrain height to available space
                const maxHeight = spaceBelow - padding * 2;
                menu.style.maxHeight = `${Math.max(maxHeight, 200)}px`;
                menu.style.overflowY = 'auto';
              }
            }

            // Final check - ensure menu doesn't go off screen
            const finalRect = menu.getBoundingClientRect();
            if (finalRect.top < padding) {
              menu.style.top = `${padding - buttonRect.top + buttonRect.height}px`;
              menu.style.bottom = 'auto';
              menu.style.marginTop = '0';
              menu.style.marginBottom = '';
            }

            if (finalRect.bottom > windowHeight - padding) {
              const availableSpace = windowHeight - buttonRect.top - padding;
              if (availableSpace > 200) {
                menu.style.maxHeight = `${availableSpace}px`;
                menu.style.overflowY = 'auto';
              } else {
                // Position above if there's more space
                menu.style.top = 'auto';
                menu.style.bottom = '100%';
                menu.style.marginTop = '0';
                menu.style.marginBottom = '4px';
                menu.style.maxHeight = '';
                menu.style.overflowY = '';
              }
            }
          }, 10);
        }
      }
    };

    if (showMenu) {
      // For both grid and list view, adjust menu position
      document.addEventListener('mousedown', handleClickOutside);

      // Adjust position immediately and on resize/scroll
      setTimeout(adjustMenuPosition, 0);
      window.addEventListener('resize', adjustMenuPosition);
      window.addEventListener('scroll', adjustMenuPosition, true);

      return () => {
        document.removeEventListener('mousedown', handleClickOutside);
        window.removeEventListener('resize', adjustMenuPosition);
        window.removeEventListener('scroll', adjustMenuPosition, true);
      };
    }

    if (isHovered && viewMode === 'grid') {
      // For grid view, also adjust on hover
      const positionMenu = () => {
        adjustMenuPosition();
        if (isHovered) {
          requestAnimationFrame(positionMenu);
        }
      };
      positionMenu();
      window.addEventListener('scroll', adjustMenuPosition, true);
      window.addEventListener('resize', adjustMenuPosition);
      return () => {
        window.removeEventListener('scroll', adjustMenuPosition, true);
        window.removeEventListener('resize', adjustMenuPosition);
      };
    }
  }, [showMenu, isHovered, viewMode]);

  const handleFileClick = (e) => {
    // Don't trigger download if clicking on action buttons, menu, or checkbox
    if (e.target.closest('.file-actions') || 
        e.target.closest('.btn-icon') || 
        e.target.closest('.file-menu') ||
        e.target.closest('.file-menu-btn') ||
        e.target.closest('.file-checkbox') ||
        e.target.type === 'checkbox') {
      return;
