    // If Ctrl/Cmd is held, toggle selection
    if (e.ctrlKey || e.metaKey) {
      if (onSelect) {
        onSelect(file.id, 'file');
      }
      return;
    }
    // Trigger download on file click
    if (onDownload) {
      onDownload(file.id);
    }
  };

